import React, { memo, useMemo } from "react";

function formatNumber(value) {
  return value.toLocaleString("en-IN", { maximumFractionDigits: 2 });
}

function formatChange(value) {
  const prefix = value > 0 ? "+" : "";
  return `${prefix}${value.toFixed(2)}%`;
}

function getTrend(currentPrice, dayOpen) {
  if (currentPrice === dayOpen) return "flat";
  return currentPrice > dayOpen ? "up" : "down";
}

function WatchlistRow({
  symbol,
  stock,
  isSelected,
  flashDirection,
  onClick,
  onRemove,
  onContextMenu,
  onDragStart,
  onDragOver,
  onDrop,
}) {
  const trend = useMemo(
    () => getTrend(stock.price, stock.open),
    [stock.price, stock.open]
  );

  return (
    <button
      type="button"
      className={`table-row data watchlist-row ${
        isSelected ? "selected" : ""
      } ${flashDirection ? `flash-${flashDirection}` : ""}`}
      onClick={onClick}
      onContextMenu={onContextMenu}
      draggable
      onDragStart={onDragStart}
      onDragOver={onDragOver}
      onDrop={onDrop}
    >
      <span className="symbol">{symbol}</span>
      <span>₹{formatNumber(stock.price)}</span>
      <span className={`change ${trend}`}>
        {formatChange(stock.change)}
      </span>
      <span className={`trend ${trend}`}>
        {trend === "up" ? "↑" : trend === "down" ? "↓" : "→"}
      </span>
    </button>
  );
}

export default memo(WatchlistRow);
